//if control has come here, assume batchemails have gone successfully
//add all emails from batchRecipients into perEmailStatus json as key and value as True

let out = {};
let rcpt=JSON.parse(`#{batchRecipients}`);
for(let i=0; i < rcpt.length; i++){
  let email = rcpt[i];
  out[email]=true;
}
console.log(JSON.stringify(out));

//to convert to an array from jsonmap, in order to be able to iterate over it
let outlist=[];
let pjson = JSON.parse(`#{recipientNotificationData}`);
for (const [recipientId, value] of Object.entries(pjson)) {
//thats why iteration on its key is needed
  let mapValue = null;
  let innerVal = JSON.parse(value.json_build_object);
  Object.keys(innerVal).forEach(function(vkey){
  // Object.keys(value).forEach(function(vkey){
  //   mapValue = value[vkey];
      mapValue = innerVal[vkey];
  });
   let newobj = {
      "key":recipientId,
      //"data":JSON.parse(mapValue)[recipientId]
      "data":mapValue
  }
   outlist.push(newobj);
}
console.log(JSON.stringify(outlist));
